import{_ as c,a8 as e,o as s,c as g,ah as l,a as r,a3 as t,K as a,L as u}from"./chunks/framework.D31WLDJp.js";import"./chunks/theme.CP9whvzN.js";const P=JSON.parse('{"title":"飞书知识库写入（lark-cli 链路）","description":"","frontmatter":{"type":"workflow","scope":"global","created":"2026-09-12T00:00:00.000Z","updated":"2026-09-12T00:00:00.000Z","tags":["飞书","lark-cli","知识库","Wiki","自动化"]},"headers":[],"relativePath":"vault/Memory/Workflows/飞书知识库写入(lark-cli链路).md","filePath":"vault/Memory/Workflows/飞书知识库写入(lark-cli链路).md","lastUpdated":1789374053000}'),k={name:"vault/Memory/Workflows/飞书知识库写入(lark-cli链路).md"};function p(m,o,_,h,b,f){const i=e("VPNolebaseInlineLinkPreview"),d=e("NolebaseGitContributors"),n=e("NolebaseGitChangelog");return s(),g("div",null,[o[3]||(o[3]=l('<h1 id="飞书知识库写入-lark-cli-链路" tabindex="-1">飞书知识库写入（lark-cli 链路） <a class="header-anchor" href="#飞书知识库写入-lark-cli-链路" aria-label="Permalink to “飞书知识库写入（lark-cli 链路）”">​</a></h1><p>把本地 Markdown 长文档 / 模板包写入飞书知识库（Wiki）的一条可协作文档节点的固定流程。 已在「AI 办公提示词模板包」（6.4 万字）端到端验证通过。</p><h2 id="前置" tabindex="-1">前置 <a class="header-anchor" href="#前置" aria-label="Permalink to “前置”">​</a></h2><ul><li><code>lark-cli</code> 已安装并 <code>lark-cli auth status --as user</code> 登录（飞书连接器 connected）。</li><li>取知识库 <code>space_id</code>：先 <code>lark-cli wiki +space-list --as user --format json</code> 找现有库，或新建。</li></ul><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to “步骤”">​</a></h2><ol><li><p><strong>建知识库（首次）</strong><code>lark-cli wiki +space-create --name &quot;知识库名&quot; --as user --format json</code> → 取返回 <code>space_id</code>。</p></li><li><p><strong>建空 docx 节点</strong><code>lark-cli wiki +node-create --space-id &lt;id&gt; --title &quot;文档标题&quot; --as user --format json</code> → 返回里 <code>document</code> 字段即 docx <code>obj_token</code>（形如 <code>FYQ3dic5...</code>）；同时返回 <code>node_token</code>（wiki 节点令牌）。</p></li><li><p><strong>写入正文（append Markdown）</strong><code>lark-cli docs +update --doc &lt;obj_token&gt; --command append --doc-format markdown --content &quot;@./file.md&quot; --as user --format json</code></p><ul><li><code>--content &quot;@./file.md&quot;</code> 支持直接吃本地 Markdown 文件（相对路径）。</li><li>可多次 append 分段写入。</li></ul></li></ol><h2 id="富文本着色-本地图片内联-xml-路径" tabindex="-1">富文本着色 + 本地图片内联（XML 路径） <a class="header-anchor" href="#富文本着色-本地图片内联-xml-路径" aria-label="Permalink to “富文本着色 + 本地图片内联（XML 路径）”">​</a></h2><p><code>--doc-format markdown</code> 只能写纯文本，且内联本地图会被拒（<code>2119 Invalid resource token</code>）。给手册 / 笔记做<strong>语义配色 + 截图内联</strong>要走 XML：</p><p><code>lark-cli docs +update --doc &lt;obj_token&gt; --command overwrite --doc-format xml --content &quot;@./styled.xml&quot; --as user</code></p><ul><li><strong>文字色 / 背景色</strong>：<code>&lt;span text-color=&quot;rgb(36,91,219)&quot;&gt;…&lt;/span&gt;</code>、<code>&lt;span background-color=&quot;rgba(186,206,253,0.7)&quot;&gt;…&lt;/span&gt;</code>。</li><li><strong>高亮块 callout</strong>：<code>&lt;callout emoji=&quot;💡&quot; background-color=&quot;rgb(240,244,255)&quot;&gt;…&lt;/callout&gt;</code>；<strong>emoji 仅支持 💡 ❗ ✅ 📌，<code>⚠️</code> 会被忽略并 fallback 成 💡</strong>——警示类改用 ❗。</li><li><strong>表格底色</strong>：<code>&lt;th background-color=&quot;rgba(245,246,247,0.9)&quot;&gt;</code>、单元格同理。</li><li><strong>本地图片内联</strong>（关键）：<code>&lt;img name=&quot;图2-1.png&quot; height=&quot;320&quot;/&gt;</code>，图片按文件名引用，<strong>顺序与源 Markdown 图注一一对应</strong>；比旧版 media-insert 分步方案稳。</li><li>一次性 <code>overwrite</code> 即可把「含图 + 含样式」的两册手册完整落地，无需 append 分段。</li></ul>',10)),r("blockquote",null,[r("p",null,[o[1]||(o[1]=t("对外发布权限坑（wiki 节点无法 API 设互联网公开）→ 见 ",-1)),a(i,{class:"route-link nolebase-route-link-invalid",href:"#",target:"_target"},{default:u(()=>[...o[0]||(o[0]=[t("Memory/Lessons/飞书wiki节点公开API失败1066001",-1)])]),_:1}),o[2]||(o[2]=t("。",-1))])]),o[4]||(o[4]=l('<h2 id="注意事项-踩过的坑" tabindex="-1">注意事项（踩过的坑） <a class="header-anchor" href="#注意事项-踩过的坑" aria-label="Permalink to “注意事项（踩过的坑）”">​</a></h2><ul><li><strong>Markdown 内联本地图被拒</strong>：<code>2119 Invalid resource token</code>；改用 XML <code>&lt;img name=&quot;…&quot;/&gt;</code> 路径（见上节）。</li><li><strong>callout emoji 限制</strong>：<code>⚠️</code> 不被接受（fallback 💡），警示块用 ❗。</li><li><strong>超长文档分段</strong>：6 万字+ 按分类切成 2–3 段分别 append，避免单次超大请求失败。</li><li><strong>Mermaid 被转白板</strong>：Markdown 中的 <code>```mermaid</code> 代码块会被渲染成飞书&quot;白板&quot; block， 内容不丢但大纲不列出其 h3 标题——属正常增强，非错误，不用重传。</li><li><strong>校验完整性</strong>：<code>lark-cli docs +fetch --doc &quot;&lt;url&gt;&quot; --scope keyword --keyword &quot;A01&quot; --context-after 1 --format json</code> 抽样核验条目 / 标题是否齐全（outline 对白板类不敏感，用 keyword 更稳）。</li><li>node-create 只建空壳，正文必须用 docs +update 写；docs +create 可一次性导入但难做长文分段与节点挂接。</li></ul><h2 id="取链接" tabindex="-1">取链接 <a class="header-anchor" href="#取链接" aria-label="Permalink to “取链接”">​</a></h2><p>节点建好后，用户可分享的文档 URL 形如 <code>https://&lt;tenant&gt;.feishu.cn/wiki/&lt;node_token&gt;</code>（node-create 返回 <code>node_token</code>）。</p><h2 id="文档操作补充坑点-帮老适时期实测补充" tabindex="-1">文档操作补充坑点（帮老适时期实测补充） <a class="header-anchor" href="#文档操作补充坑点-帮老适时期实测补充" aria-label="Permalink to “文档操作补充坑点（帮老适时期实测补充）”">​</a></h2><ul><li><strong>含白板/颜色 span 的文档禁 <code>overwrite</code></strong>：markdown 无法表达白板块，overwrite 会把刚插入的白板块删掉（实测画板被覆盖事故）；含颜色 span 的文档 overwrite 也会静默丢 span。凡含内嵌白板，文字更新必须 str_replace / block_insert。</li><li><strong>fetch 导出 XML 不序列化颜色 span</strong>：回读看不到上色，只能靠 revision 比对。</li><li><strong>doc 引用 <code>&lt;cite&gt;</code> 必须用 wiki 节点 token</strong>，用 docx obj_token 会静默丢弃。</li><li><strong><code>--content @file</code> 仅接受 cwd 相对路径</strong>；<code>str_replace --pattern</code> 不支持 @file。</li><li><strong><code>wiki +move</code> 必须带 <code>--space-id</code></strong>；<strong><code>node-delete</code> 默认级联删子树</strong>，删叶子务必 <code>--include-children=false</code>。</li><li>CLI 无节点 rename，用 copy --title 新建 + delete 旧节点替代。</li><li>whiteboard <code>+update --overwrite</code> 后首次 query image 返回旧缓存。</li></ul><h2 id="svg→png-中文渲染" tabindex="-1">SVG→PNG 中文渲染 <a class="header-anchor" href="#svg→png-中文渲染" aria-label="Permalink to “SVG→PNG 中文渲染”">​</a></h2><p>svglib→renderPDF→PyMuPDF 栅格化中文变方块（svglib 不嵌 CJK 字体）；svglib+reportlab renderPM 需 rlPyCairo（无 cairo 失败）。<strong>稳定路径 = PIL ImageDraw + 微软雅黑直接绘制</strong>。</p>',8)),a(d),a(n)])}const v=c(k,[["render",p]]);export{P as __pageData,v as default};
